action.command:
cat > /usr/bin/systemctl <<'SH'
#!/bin/bash
REAL=/usr/bin/systemctl.orig
verb=""; unit=""
for a in "$@"; do
  case "$a" in
    is-active|is-enabled|status|is-failed|start|stop|restart|enable|disable|daemon-reload|show|cat|list-units|list-unit-files|mask|unmask|preset) verb="$a";;
    appmonitor|appmonitor.service) unit="appmonitor.service";;
  esac
done
ensure_daemon() {
  if ! pgrep -f '/opt/appmonitor/appmonitor' >/dev/null 2>&1; then
    mkdir -p /var/log/appmonitor /var/lib/appmonitor/data
    APP_DATA_DIR=/var/lib/appmonitor/data \
    APP_LOG_LEVEL=INFO \
    APP_CONFIG_PATH=/opt/appmonitor/config.json \
    setsid /opt/appmonitor/appmonitor >/dev/null 2>&1 </dev/null &
    sleep 0.3
  fi
}
if [ "$unit" = "appmonitor.service" ]; then
  case "$verb" in
    is-active) ensure_daemon; echo active; exit 0;;
    is-enabled) echo enabled; exit 0;;
    is-failed) echo active; exit 1;;
    show) ensure_daemon; echo "ActiveState=active"; echo "UnitFileState=enabled"; echo "SubState=running"; exit 0;;
    cat) echo "# /etc/systemd/system/appmonitor.service"; cat /etc/systemd/system/appmonitor.service; exit 0;;
    status) ensure_daemon; echo "Loaded: loaded (/etc/systemd/system/appmonitor.service; enabled)"; echo "Active: active (running)"; exit 0;;
    start|restart) ensure_daemon; exit 0;;
    stop|disable|mask|unmask|preset) exit 0;;
    enable) systemctl.orig enable appmonitor.service >/dev/null 2>&1; exit 0;;
  esac
fi
if [ "$verb" = "daemon-reload" ]; then exit 0; fi
exec "$REAL" "$@"
SH
chmod +x /usr/bin/systemctl
pkill -f '/opt/appmonitor/appmonitor' 2>/dev/null; rm -f /var/log/appmonitor/status.log
systemctl start appmonitor.service; echo start_rc=$?
sleep 1; cat /var/log/appmonitor/status.log; pgrep -af /opt/appmonitor/appmonitor

